        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                ReadData();
                EndProcess();
            }
        }

        private void ReadData()
        {
            SIM_Branch obj = new SIM_Branch();

            dtbData = obj.GetDataTable(
                "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
                "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
                "@TeacherID", lookupTeacherID.EditValue,
                "@YearID", uYearSemester.YearIDEditValue,
                "@Semester", uYearSemester.SemesterEditValue
            );

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                gcData.DataSource = null;
                MessageManager.Warning("Không có dữ liệu!");
                return;
            }

            InitGrid();
            gcData.DataSource = dtbData;
            gvData.BestFitColumns();
        }

        private void InitGrid()
        {
            gvData.Bands.Clear();
            gvData.Columns.Clear();
            gvData.SummaryCollection = "";

            if (dtbData == null || dtbData.Columns.Count == 0)
                return;

            // Band: GIẢNG VIÊN
            GridBand gbTeacher = CreateBand("GIẢNG VIÊN");

            // Band: COI THI / CHẤM THI
            GridBand gbExam = CreateBand("COI THI / CHẤM THI");

            // Band: GIỜ CHUẨN / KIÊM NHIỆM
            GridBand gbStandard = CreateBand("GIỜ CHUẨN / KIÊM NHIỆM");

            // Band: CV HỌC TẬP / HOẠT ĐỘNG KHÁC
            GridBand gbCV = CreateBand("CV HỌC TẬP / HOẠT ĐỘNG KHÁC");

            // Band: NCKH
            GridBand gbNCKH = CreateBand("NCKH");

            // Band: GIẢNG DẠY THỰC TẾ
            GridBand gbTeaching = CreateBand("GIẢNG DẠY THỰC TẾ");

            // Duyệt từng cột trong DataTable và phân vào band phù hợp
            foreach (DataColumn dc in dtbData.Columns)
            {
                string colName = dc.ColumnName;
                string caption = colName;
                int width = GetDefaultWidth(colName);
                string format = GetDefaultFormat(colName);
                DevExpress.Utils.HorzAlignment align = GetDefaultAlignment(colName);

                GridBand targetBand = GetBandForColumn(colName,
                    gbTeacher, gbExam, gbStandard, gbCV, gbNCKH, gbTeaching);

                if (targetBand == null)
                {
                    // Cột không được phân vào band, tạo band mặc định
                    targetBand = gbTeaching;
                }

                BandedGridColumn col = new BandedGridColumn();
                col.FieldName = colName;
                col.Caption = caption;
                col.Name = "gcol" + colName;
                col.Visible = true;
                col.Width = width;

                col.AppearanceHeader.Options.UseTextOptions = true;
                col.AppearanceHeader.TextOptions.HAlignment =
                    DevExpress.Utils.HorzAlignment.Center;

                col.AppearanceCell.Options.UseTextOptions = true;
                col.AppearanceCell.TextOptions.HAlignment = align;

                if (!string.IsNullOrEmpty(format))
                {
                    col.DisplayFormat.FormatString = format;
                    col.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
                }

                gvData.Columns.Add(col);
                targetBand.Columns.Add(col);

                // Highlight các cột tính toán
                HighlightColumnIfNeeded(colName, col);
            }

            // Tổng hợp SummaryCollection cho các cột số
            BuildSummaryCollection();
        }

        private GridBand CreateBand(string caption)
        {
            GridBand band = new GridBand();
            band.Caption = caption;
            band.AppearanceHeader.Font = new Font("Tahoma", 9, FontStyle.Bold);
            band.AppearanceHeader.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Center;
            gvData.Bands.Add(band);
            return band;
        }

        private GridBand GetBandForColumn(string colName,
            GridBand gbTeacher, GridBand gbExam, GridBand gbStandard,
            GridBand gbCV, GridBand gbNCKH, GridBand gbTeaching)
        {
            string upper = colName.ToUpper();

            // GIẢNG VIÊN
            if (upper.Contains("TEACHERID")
                || upper.Contains("TEACHERFIRSTNAME")
                || upper.Contains("TEACHERLASTNAME")
                || upper.Contains("TEACHERNAME")
                || colName == "TeacherName")
                return gbTeacher;

            // COI THI / CHẤM THI
            if (upper.Contains("COITHI")
                || upper.Contains("CHAMTHI")
                || upper.Contains("GIOQUYDOI_COITHI")
                || upper.Contains("GIOQUYDOI_CHAMTHI")
                || upper.Contains("SOGIO_COITHI")
                || upper.Contains("SOBAI_CHAMTHI"))
                return gbExam;

            // GIỜ CHUẨN / KIÊM NHIỆM
            if (upper.Contains("STANDARDQUANTITY")
                || upper.Contains("RATIOPOSITION")
                || upper.Contains("REALSTANDARDQUANTITY")
                || upper.Contains("DINHMUC"))
                return gbStandard;

            // CV HỌC TẬP / HOẠT ĐỘNG KHÁC
            if (upper.Contains("W34")
                || upper.Contains("W35")
                || upper.Contains("HOCTAP")
                || upper.Contains("BOIDUONG")
                || upper.Contains("HOATDONG"))
                return gbCV;

            // NCKH
            if (upper.Contains("NCKH")
                || upper.Contains("RESEARCH"))
                return gbNCKH;

            // GIẢNG DẠY THỰC TẾ (mặc định)
            return gbTeaching;
        }

        private int GetDefaultWidth(string colName)
        {
            string upper = colName.ToUpper();

            if (upper.Contains("TEACHERID"))
                return 80;
            if (upper.Contains("FIRSTNAME") || upper.Contains("LASTNAME"))
                return 120;
            if (upper.Contains("TEACHERNAME"))
                return 180;
            if (upper.Contains("HESO"))
                return 70;
            if (upper.Contains("QUYDOI") || upper.Contains("DINHMUC"))
                return 110;

            return 100;
        }

        private string GetDefaultFormat(string colName)
        {
            string upper = colName.ToUpper();

            // Cột text (không format số)
            if (upper.Contains("TEACHERID")
                || upper.Contains("FIRSTNAME")
                || upper.Contains("LASTNAME")
                || upper.Contains("TEACHERNAME"))
                return "";

            // Cột hệ số
            if (upper.Contains("HESO"))
                return "#,##0.00";

            // Các cột số còn lại
            if (upper.Contains("QUANTITY")
                || upper.Contains("QUYDOI")
                || upper.Contains("GIO")
                || upper.Contains("SO")
                || upper.Contains("DINHMUC")
                || upper.Contains("TONG")
                || upper.Contains("NCKH")
                || upper.Contains("W34")
                || upper.Contains("W35")
                || upper.Contains("TOTAL")
                || upper.Contains("RESEARCH"))
                return "#,##0.00";

            return "";
        }

        private DevExpress.Utils.HorzAlignment GetDefaultAlignment(string colName)
        {
            string upper = colName.ToUpper();

            // Cột text: căn trái
            if (upper.Contains("FIRSTNAME")
                || upper.Contains("LASTNAME")
                || upper.Contains("TEACHERNAME"))
                return DevExpress.Utils.HorzAlignment.Near;

            // Mặc định căn giữa
            return DevExpress.Utils.HorzAlignment.Center;
        }

        private void HighlightColumnIfNeeded(string colName, BandedGridColumn col)
        {
            string upper = colName.ToUpper();

            // Highlight Tổng LT+TH
            if (upper.Contains("TONGLTTH"))
            {
                col.AppearanceCell.BackColor = Color.FromArgb(255, 255, 192);
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
                col.AppearanceCell.Options.UseFont = true;
            }

            // Highlight Quy đổi giờ
            if (upper.Contains("QUYDOIGIO") && !upper.Contains("COITHI") && !upper.Contains("CHAMTHI"))
            {
                col.AppearanceCell.BackColor = Color.LightSkyBlue;
                col.AppearanceCell.Options.UseBackColor = true;
                col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
                col.AppearanceCell.Options.UseFont = true;
            }
        }

        private void BuildSummaryCollection()
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();

            foreach (DataColumn dc in dtbData.Columns)
            {
                string upper = dc.ColumnName.ToUpper();

                // Chỉ tính tổng cho các cột số
                if (dc.DataType == typeof(decimal)
                    || dc.DataType == typeof(double)
                    || dc.DataType == typeof(int)
                    || dc.DataType == typeof(long)
                    || dc.DataType == typeof(float))
                {
                    // Bỏ qua TeacherID và các cột ID
                    if (upper == "TEACHERID")
                        continue;

                    if (sb.Length > 0)
                        sb.Append(",");
                    sb.Append(dc.ColumnName);
                }
            }

            gvData.SummaryCollection = sb.ToString();
        }

        private void BeginProcess()
        {
            btnSearch.Enabled = btnClose.Enabled = false;
        }

        private void EndProcess()
        {
            btnSearch.Enabled = btnClose.Enabled = true;
        }

        private bool IsValidData()
        {
            if (uYearSemester.YearIDEditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn niên học!");
                uYearSemester.Focus();
                return false;
            }

            return true;
        }

