private void ExportToTemplate()
{
    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    try
    {
        string templatePath = Application.StartupPath + "\\maubaoacao.xlsx";

        if (!System.IO.File.Exists(templatePath))
        {
            MessageManager.Warning("Không tìm thấy file mẫu: " + templatePath);
            return;
        }

        SaveFileDialog saveDialog = new SaveFileDialog();
        saveDialog.Filter = "Excel Files|*.xlsx";
        saveDialog.Title = "Lưu báo cáo";
        saveDialog.FileName = "BaoCao_KetQuaThucHienNhaGiao_" +
            DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".xlsx";

        if (saveDialog.ShowDialog() != DialogResult.OK)
            return;

        System.IO.File.Copy(templatePath, saveDialog.FileName, true);

        Microsoft.Office.Interop.Excel.Application excelApp =
            new Microsoft.Office.Interop.Excel.Application();
        Microsoft.Office.Interop.Excel.Workbook workbook = null;
        Microsoft.Office.Interop.Excel.Worksheet worksheet = null;

        try
        {
            excelApp.Visible = false;
            excelApp.DisplayAlerts = false;

            workbook = excelApp.Workbooks.Open(saveDialog.FileName);
            worksheet = (Microsoft.Office.Interop.Excel.Worksheet)workbook.Worksheets[1];

            // Xóa dữ liệu cũ (từ dòng 18 đến 288)
            Microsoft.Office.Interop.Excel.Range deleteRange =
                worksheet.Rows["18:288"];
            deleteRange.Delete(
                Microsoft.Office.Interop.Excel.XlDeleteShiftDirection.xlShiftUp);

            // Cập nhật tiêu đề năm học
            string yearText = "";
            if (uYearSemester.YearIDEditValue != null)
            {
                object yearObj = uYearSemester.YearIDEditValue;
                if (yearObj is int)
                    yearText = yearObj.ToString();
                else
                    yearText = yearObj.ToString();
            }

            // Điền dữ liệu
            int startRow = 18;
            int row = startRow;

            for (int i = 0; i < dtbData.Rows.Count; i++)
            {
                DataRow dr = dtbData.Rows[i];

                // TT tổng
                worksheet.Cells[row, 1] = i + 1;
                // TT đơn vị
                worksheet.Cells[row, 2] = i + 1;
                // Họ và tên
                worksheet.Cells[row, 3] = GetStringValue(dr, "TeacherName");
                // Định mức giảng dạy
                worksheet.Cells[row, 4] = GetDecimalValue(dr, "StandardQuantity_DinhMucGiangDay");
                // Định mức giảm kiêm nhiệm
                worksheet.Cells[row, 5] = GetDecimalValue(dr, "RatioPositionValue_DinhMucGiamKiemNhiem");
                // Định mức GD năm học = (4) - (5)
                Microsoft.Office.Interop.Excel.Range cellF =
                    (Microsoft.Office.Interop.Excel.Range)worksheet.Cells[row, 6];
                cellF.Formula = "=D" + row + "-E" + row;

                // Số giờ học tập, bồi dưỡng
                worksheet.Cells[row, 7] = GetDecimalValue(dr, "TotalFinal_W34_HocTapBoiDuong");
                // Công việc khác
                worksheet.Cells[row, 8] = GetDecimalValue(dr, "TotalFinal_W35_HoatDongKhac");
                // Số giờ NCKH
                worksheet.Cells[row, 9] = GetDecimalValue(dr, "ResearchNow_NCKH");
                // Số giờ giảng dạy thực tế
                worksheet.Cells[row, 10] = GetDecimalValue(dr, "TongLTTH");
                // Tổng số giờ ra đề, coi thi/chấm thi
                decimal coiThi = GetDecimalValue(dr, "GioQuyDoi_CoiThi");
                decimal chamThi = GetDecimalValue(dr, "GioQuyDoi_ChamThi");
                worksheet.Cells[row, 11] = coiThi + chamThi;

                // Tổng số giờ giảng dạy, hoạt động = F + G + H + I + J + K
                Microsoft.Office.Interop.Excel.Range cellL =
                    (Microsoft.Office.Interop.Excel.Range)worksheet.Cells[row, 12];
                cellL.Formula = "=F" + row + "+G" + row + "+H" + row
                    + "+I" + row + "+J" + row + "+K" + row;

                // Định mức tổng (để trống, nhập tay)
                // worksheet.Cells[row, 13] = "";

                // Vượt/Thiếu = L - M
                Microsoft.Office.Interop.Excel.Range cellN =
                    (Microsoft.Office.Interop.Excel.Range)worksheet.Cells[row, 14];
                cellN.Formula = "=L" + row + "-M" + row;

                row++;
            }

            // Ghi dòng tổng kết
            row++;
            worksheet.Cells[row, 1] = "Danh sách trên có " +
                dtbData.Rows.Count + " nhà giáo.";

            // Merge dòng tổng kết cho đẹp
            Microsoft.Office.Interop.Excel.Range summaryRange =
                worksheet.Range[
                    worksheet.Cells[row, 1],
                    worksheet.Cells[row, 16]];
            summaryRange.Merge(Type.Missing);
            summaryRange.Font.Bold = true;

            // Định dạng cột số
            Microsoft.Office.Interop.Excel.Range numberRange =
                worksheet.Range[
                    worksheet.Cells[startRow, 4],
                    worksheet.Cells[startRow + dtbData.Rows.Count - 1, 14]];
            numberRange.NumberFormat = "#,##0.00";

            // Canh giữa các cột số thứ tự
            Microsoft.Office.Interop.Excel.Range sttRange =
                worksheet.Range[
                    worksheet.Cells[startRow, 1],
                    worksheet.Cells[startRow + dtbData.Rows.Count - 1, 2]];
            sttRange.HorizontalAlignment =
                Microsoft.Office.Interop.Excel.XlHAlign.xlHAlignCenter;

            // Fit column width
            worksheet.Columns.AutoFit();

            workbook.Save();
            MessageManager.Information("Đã xuất báo cáo thành công!");
            System.Diagnostics.Process.Start(saveDialog.FileName);
        }
        finally
        {
            if (workbook != null)
            {
                workbook.Close(false, Type.Missing, Type.Missing);
                System.Runtime.InteropServices.Marshal.ReleaseComObject(workbook);
            }

            if (worksheet != null)
                System.Runtime.InteropServices.Marshal.ReleaseComObject(worksheet);

            excelApp.Quit();
            System.Runtime.InteropServices.Marshal.ReleaseComObject(excelApp);
        }
    }
    catch (Exception ex)
    {
        MessageManager.Error("Lỗi khi xuất báo cáo: " + ex.Message);
    }
}

private string GetStringValue(DataRow dr, string colName)
{
    if (dr.Table.Columns.Contains(colName) && dr[colName] != DBNull.Value)
        return dr[colName].ToString();
    return "";
}

private decimal GetDecimalValue(DataRow dr, string colName)
{
    if (dr.Table.Columns.Contains(colName) && dr[colName] != DBNull.Value)
    {
        decimal val = 0;
        decimal.TryParse(dr[colName].ToString(), out val);
        return val;
    }
    return 0;
}

